      if (focusReclaimAttemptsForPanelRuntime >= FOCUS_RECLAIM_MAX_ATTEMPTS_FOR_PANEL_RUNTIME) return;
      const editableElForPanelRuntime = lastFocusForPanelRuntime.el;
