      S.sidebarCollapsed = true;
      root.getElementById('chat-sidebar').classList.add('collapsed');
      root.getElementById('chat-main').classList.add('sidebar-is-collapsed');
      writePanelStateSyncForPanelRuntime({ sidebarCollapsed: true });
